def search(arr, target):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def search_target(arr, target):
    for index, value in enumerate(arr):
        if value == target:
            return index
    return -1


arr = [4, 1, 7, 3, 9]
target = 7

result = search_target(arr, target)
print(result)

